import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root object (already positioned by adapter)
  const root = new Group();

  // Geometry & material
  const geometry = new PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  const mesh = new ctx.THREE.Mesh(geometry, material);
  root.add(mesh);

  // Load texture async, assign when ready
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  let texture = null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Preserve original Y for hover revert
  const originalY = root.position.y;

  // Store timelines for cleanup
  const timelines = [];

  // Event handlers
  root.userData.handlers = {
    hover: () => {
      const tl = gsap.timeline();
      tl.to(root.position, {
        y: originalY + 0.15,
        duration: 0.5,
        ease: 'power3.out',
      });
      timelines.push(tl);
    },
    unhover: () => {
      const tl = gsap.timeline();
      tl.to(root.position, {
        y: originalY,
        duration: 0.5,
        ease: 'power3.out',
      });
      timelines.push(tl);
    },
    click: () => {
      ctx.emit('hub-journal.select');
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose resources
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // Kill GSAP timelines
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    // Remove handlers reference
    delete root.userData.handlers;
    delete root.userData.cleanup;
  };

  return root;
}
